func merge(ctx context.Context, ins ...<-chan Row) <-chan Row {
	out := make(chan Row, 64)
	for _, in := range ins {
		go func() {
			for r := range in {
				out <- r
			}
		}()
	}
	go func() {
		time.Sleep(time.Second) // give forwarders time to drain
		close(out)
	}()
	return out
}
